// 实际开发App用的自包含合成语音，全部由业务服务建立；不认证真实微信关联。
import {fixture} from '../../media-support.mjs';
import {VoiceMediaAdapter} from '../../../src/media/voice/adapter.ts';
import {SilkWasmDecoder} from '../../../src/media/voice/decoder.ts';
import {encode} from 'silk-wasm';
import {createHash} from 'node:crypto';
import {writeFile} from 'node:fs/promises';
import path from 'node:path';
const pcm=Buffer.alloc(9600);for(let i=0;i<4800;i++)pcm.writeInt16LE(Math.round(4000*Math.sin(2*Math.PI*440*i/24000)),i*2);
const {data:silk}=await encode(pcm,24000);const wasm=new SilkWasmDecoder();let fail=true;
const source={read:async c=>({expectedBytes:silk.length,expectedSha256:createHash('sha256').update(silk).digest('hex'),bytes:(async function*(){yield silk;})(),finish:async()=>({protocol:'voice-complete-read-v1',complete:true,expectedBytes:silk.length,association:{protocol:'media-association-v1',profileId:'synthetic-voice-desktop-v1',recordId:c.source.recordId,messageId:c.messageId,resourceIdentity:'synthetic-tone-200ms'}})})};
const adapter=new VoiceMediaAdapter({source,decoder:{decode:async(...args)=>{if(fail)throw Error('合成首轮转换失败');return wasm.decode(...args);},close:()=>wasm.close()}});
const f=await fixture({after(){}},adapter);const first=f.messages.find(m=>m.kind==='voice');const limited=await f.media.extract(f.contact,first.id,{requestKey:'desktop-voice-limited',goal:'extract'});
const second=f.saved[1].contact_id;await f.history.synchronize(second);const secondVoice=(await f.history.read(second)).messages.find(m=>m.kind==='voice');fail=false;const full=await f.media.extract(second,secondVoice.id,{requestKey:'desktop-voice-full',goal:'extract'});
await f.contacts.setReading(false);const databaseId=f.storage.status.databaseId;await f.media.close();await f.history.close();await f.contacts.close();await f.storage.close();
const project=path.resolve(new URL('../../../../',import.meta.url).pathname);
await writeFile(path.join(f.root,'backend-launch.json'),JSON.stringify({projectDirectory:project,envFilePath:path.join(f.root,'unused.env'),backendInfoPath:path.join(f.root,'managed/sqlite-backend.info')}),{mode:0o600});
await writeFile(path.join(f.root,'sqlite-development.json'),JSON.stringify({formatVersion:1,intent:'open',role:'test',expectedDatabaseId:databaseId,capabilities:['contacts','history']}),{mode:0o600});
await writeFile(path.join(f.root,'unused.env'),'# 隔离合成语音，不设置模型或真实渠道\n',{mode:0o600});
await writeFile(path.join(f.root,'voice-acceptance.json'),JSON.stringify({root:f.root,databaseId,ownerId:f.owner,contactId:f.contact,secondContactId:second,voiceId:first.id,secondVoiceId:secondVoice.id,voiceSource:first.sourceRecordIds[0],limitedFiles:limited.files,fullFiles:full.files}),{mode:0o600});
console.log(JSON.stringify({root:f.root,databaseId,readEnabled:false,synthetic:true,silkBytes:silk.length,expectedPcmBytes:9600,limitedFiles:limited.files.length,fullFiles:full.files.length}));
